public class Gen<T, T2> {
    private T data1;
    private T2 data2;

    public void setValue(T dt1, T2 dt2) {
        data1 = dt1;
        data2 = dt2;
    }

    public T getT1Value() {
        return data1;
    }

    public T2 getT2Value() {
        return data2;
    }
}

Gen<Integer, String> mixData = new Gen<>();
Gen<Integer, Integer> iData = new Gen<>();

mixData.setValue(1, "One");
iData.setValue(7, 25);

System.out.println("First pair: " + mixData.getT1Value() + " and " + mixData.getT2Value());
System.out.println("Second pair: " + iData.getT1Value() + " and " + iData.getT2Value());
// First pair: 1 and One
// Second pair: 7 and 25
